from robot.api import logger


class TeardownException(Exception):
    pass


class TeardownExecutor(object):
    @staticmethod
    def execute_teardown_methods(method_list):
        '''
        Allows to execute all selected method without breaking the test.
        If one method will fail, teardown will be continued
        :param method_list: method list or lists of tuple(method, kwargs)

        method_list examples:
        [method1, method2]
        [(method1, {"xyz" : 1}), (method2, {"abc": 2})]
        '''
        failed_methods = []
        method_list = _prepare_list_of_tuples_method(method_list)
        for method, kwargs in method_list:
            try:
                method(**kwargs)
            except Exception as e:
                logger.error("[Teardown] method: {} failed.\n" "Error details: {}".format(method.__name__, str(e)))
                failed_methods.append(method.__name__)
        if failed_methods:
            raise TeardownException('Teardown methods FAILED: {}'.format(failed_methods))


def _prepare_list_of_tuples_method(method_list):
    for index, method in enumerate(method_list):
        if not isinstance(method, tuple):
            method_list[index] = (method, {})
    return method_list
